import java.util.*;
public class E {
    private static final int INFINITY = 1000000000;
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int m = input.nextInt();
        if (n > m) {
            int temp = n; n = m; m = temp;
        }
        int sizeN = 1 << n;
        int[][] dpTable = new int[sizeN][sizeN];
        for (int[] row : dpTable) Arrays.fill(row, INFINITY);
        Arrays.fill(dpTable[0], 0);
        for (int step = 0; step < m; step++) {
            int[][] nextTable = new int[sizeN][sizeN];
            for (int[] row : nextTable) Arrays.fill(row, INFINITY);
            for (int prevC0 = 0; prevC0 < sizeN; prevC0++) {
                for (int prevC1 = 0; prevC1 < sizeN; prevC1++) {
                    if (dpTable[prevC0][prevC1] != INFINITY) {
                        int limitC2 = (step == m - 1) ? 1 : sizeN;
                        for (int c2 = 0; c2 < limitC2; c2++) {
                            int allBits = sizeN - 1;
                            int doneBits = (allBits & (prevC1 >> 1)) | (allBits & (prevC1 << 1)) | prevC0 | c2;
                            doneBits &= (allBits ^ prevC1);
                            int cost = dpTable[prevC0][prevC1] + n - Integer.bitCount(doneBits);
                            if (cost < nextTable[prevC1][c2]) {
                                nextTable[prevC1][c2] = cost;
                            }
                        }
                    }
                }
            }
            dpTable = nextTable;
        }
        int minCost = INFINITY;
        for (int[] row : dpTable) {
            for (int val : row) {
                if (val < minCost) minCost = val;
            }
        }
        System.out.println(n * m - minCost);
    }
}
